"""Small text statistics utilities.

Pure, dependency-free helpers for counting words and characters.
"""

from __future__ import annotations

from collections import Counter

__all__ = ["word_count", "char_frequency", "top_words"]


def _require_str(value: object, name: str = "text") -> str:
    if not isinstance(value, str):
        raise TypeError(f"{name} must be str, got {type(value).__name__}")
    return value


def word_count(text: str) -> int:
    """Return the number of whitespace-separated tokens in ``text``."""
    return len(_require_str(text).split())


def char_frequency(text: str) -> dict[str, int]:
    """Return case-insensitive character counts, ignoring whitespace."""
    text = _require_str(text)
    counts: Counter[str] = Counter()
    for ch in text:
        if not ch.isspace():
            counts[ch.lower()] += 1
    return dict(counts)


def top_words(text: str, n: int = 3) -> list[tuple[str, int]]:
    """Return the ``n`` most common lowercased words.

    Ties are broken alphabetically for deterministic output.
    """
    text = _require_str(text)
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError(f"n must be int, got {type(n).__name__}")
    if n < 0:
        raise ValueError("n must be non-negative")

    counts: Counter[str] = Counter(word.lower() for word in text.split())
    ordered = sorted(counts.items(), key=lambda item: (-item[1], item[0]))
    return ordered[:n]

import pytest

from textstats import char_frequency, top_words, word_count


def test_word_count_empty():
    assert word_count("") == 0


def test_word_count_basic():
    assert word_count("hello world  again") == 3


def test_word_count_type_error():
    with pytest.raises(TypeError):
        word_count(None)


def test_char_frequency_ignores_whitespace_and_case():
    assert char_frequency("Aa b") == {"a": 2, "b": 1}


def test_char_frequency_empty():
    assert char_frequency("") == {}


def test_char_frequency_type_error():
    with pytest.raises(TypeError):
        char_frequency(123)


def test_top_words_ordering():
    assert top_words("b a b c a b", n=2) == [("b", 3), ("a", 2)]


def test_top_words_tie_break_alphabetical():
    assert top_words("b a", n=2) == [("a", 1), ("b", 1)]


def test_top_words_n_larger_than_vocab():
    assert top_words("one two", n=10) == [("one", 1), ("two", 1)]


def test_top_words_case_insensitive():
    assert top_words("Hello hello HELLO", n=1) == [("hello", 3)]


def test_top_words_invalid_n():
    with pytest.raises(ValueError):
        top_words("a b", n=-1)
    with pytest.raises(TypeError):
        top_words("a b", n="2")

